'use strict';
// Buildless by design: also works when index.html is opened directly.
const $ = s => document.querySelector(s);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid = () => globalThis.crypto?.randomUUID?.() || 'id-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2);
const dateKey = (d = new Date()) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const day = () => dateKey();
const shiftDay = n => {const d = new Date(); d.setDate(d.getDate()+n); return dateKey(d)};
const money = n => new Intl.NumberFormat('uz-UZ').format(Math.round(Number(n) || 0));
const cash = n => `<span class="money">${money(n)}</span>`;
const sum = a => a.reduce((s,t) => s + t.amount,0);
const prettyDate = s => {if(!s)return 'Belgilanmagan';return new Date(s+'T12:00:00').toLocaleDateString('uz-UZ',{day:'numeric',month:'short',year:'numeric'})};
const daysBetween = (a,b) => Math.round((new Date(b+'T12:00:00') - new Date(a+'T12:00:00'))/86400000);
const paths = {
  home:'M3 10l9-7 9 7M5 9v12h14V9M9 21v-8h6v8', grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',
  swap:'M4 7h15M15 3l4 4-4 4M20 17H5M9 13l-4 4 4 4',users:'M16 21v-2a4 4 0 00-4-4H6a4 4 0 00-4 4v2M16 3a4 4 0 010 8M22 21v-2a4 4 0 00-3-3.87M13 7a4 4 0 11-8 0 4 4 0 018 0',
  target:'M22 12a10 10 0 11-10-10M18 12a6 6 0 11-6-6M12 12l9-9M16 3h5v5',hand:'M3 12l4-4 4 2 4-2 6 5-5 6-5-1-5-4M3 9v7M21 10v7M8 12l4 3 3-3',calendar:'M4 5h16v16H4zM4 10h16M8 3v4M16 3v4M8 14h2M14 14h2M8 17h2',
  chart:'M4 3v18h17M8 16v-4M13 16V8M18 16V5',settings:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1zM15 12a3 3 0 11-6 0 3 3 0 016 0',
  plus:'M12 5v14M5 12h14',close:'M6 6l12 12M18 6L6 18',arrow:'M5 12h14M14 7l5 5-5 5',up:'M7 17L17 7M7 7h10v10',down:'M17 7L7 17M7 7v10h10',
  eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12M15 12a3 3 0 11-6 0 3 3 0 016 0',moon:'M21 13a9 9 0 11-10-10 7 7 0 0010 10',sun:'M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1M16 12a4 4 0 11-8 0 4 4 0 018 0',
  bell:'M18 8a6 6 0 00-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',edit:'M16 3l5 5-12 12-6 1 1-6zM13 6l5 5',trash:'M3 6h18M8 6V3h8v3M5 6l1 15h12l1-15M10 10v7M14 10v7',
  search:'M21 21l-6-6M17 10a7 7 0 11-14 0 7 7 0 0114 0',download:'M12 3v12M7 10l5 5 5-5M4 16v5h16v-5',upload:'M12 16V4M7 9l5-5 5 5M4 17v4h16v-4',check:'M4 12l5 5L20 6',wallet:'M20 8V5H4v15h16V8H4M16 11h5v5h-5z',repeat:'M4 8h15l-4-4M20 16H5l4 4M19 8v4M5 16v-4',spark:'M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z',print:'M6 9V3h12v6M6 17H3V9h18v8h-3M6 14h12v7H6z',calculator:'M5 2h14v20H5zM8 5h8v4H8zM8 13h1M15 13h1M8 17h1M15 17h1'};
const icon = n => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n] || paths.spark}"/></svg>`;
function paintIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon)})}
const cats = {'Oziq-ovqat':['🥑','#387b5d'],'Transport':['🚕','#91ad77'],'Xaridlar':['🛍️','#b7cb91'],'Uy va kommunal':['🏠','#d8bd84'],'Salomatlik':['💊','#9daba2'],'Ta’lim':['📚','#7a9ea0'],'Ko‘ngilochar':['🎟️','#c4b1a1'],'Boshqa':['◈','#d0d9c4']};
function seed(){return {version:2,demo:true,budget:6000000,members:['Men','Turmush o‘rtog‘im'],settings:{name:'Bizning oila',theme:'light',privacy:false,motion:true},limits:{'Oziq-ovqat':2000000,'Transport':500000,'Xaridlar':800000},transactions:[
 {id:uid(),name:'Oylik maosh',amount:8500000,type:'income',category:'Boshqa',member:'Men',date:shiftDay(-6),method:'Karta'},
 ...[['Haftalik bozorlik',325000,'Oziq-ovqat',0],['Taksi',28000,'Transport',0],['Internet to‘lovi',150000,'Uy va kommunal',-1],['Yangi kiyimlar',240000,'Xaridlar',-2],['Oilaviy kechki ovqat',180000,'Oziq-ovqat',-3],['Kitoblar',95000,'Ta’lim',-4],['Yoqilg‘i',200000,'Transport',-5],['Bozorlik',420000,'Oziq-ovqat',-6],['Dorixona',85000,'Salomatlik',-8],['Dam olish',160000,'Ko‘ngilochar',-9]].map(([name,amount,category,offset],i)=>({id:uid(),name,amount,type:'expense',category,member:i%2?'Men':'Turmush o‘rtog‘im',date:shiftDay(offset),method:i%2?'Karta':'Naqd'}))],
 goals:[{id:uid(),name:'Yangi telefon',target:12000000,saved:4500000,icon:'📱',date:shiftDay(150)},{id:uid(),name:'Oilaviy ta’til',target:20000000,saved:8200000,icon:'🏝️',date:shiftDay(240)},{id:uid(),name:'Orzudagi uy',target:150000000,saved:12000000,icon:'🏡',date:shiftDay(730)}],
 debts:[{id:uid(),name:'Aziz',amount:500000,repaid:0,date:shiftDay(3),type:'lent',paid:false},{id:uid(),name:'Dilshod',amount:1200000,repaid:400000,date:shiftDay(12),type:'borrowed',paid:false}],
 bills:[{id:uid(),name:'Internet',amount:150000,date:shiftDay(4),category:'Uy va kommunal',frequency:'monthly'},{id:uid(),name:'Ingliz tili kursi',amount:650000,date:shiftDay(7),category:'Ta’lim',frequency:'monthly'}]}}
function normalize(s){return BarakaData.normalize(s)}
let state,storageOK=true;
try{const raw=localStorage.getItem('baraka-v1');state=normalize(raw?JSON.parse(raw):seed())}catch(e){state=normalize(seed());storageOK=false}
globalThis.barakaCloud=null;
try{const p=JSON.parse(localStorage.getItem('baraka-preferences')||'null');if(p){state.settings.theme=p.theme==='dark'?'dark':'light';state.settings.privacy=p.privacy===true;state.settings.motion=p.motion!==false}}catch{}
let modalCanSubmit=false;
let page='home',formType='',activeId='',reportPeriod='week',toastTimer,undoAction=null,pendingAction=null,quickPreset=null;
const titles={...globalThis.BarakaLife?.titles,...BarakaDay.titles,...BarakaFavorites.titles,home:['Hammasi o‘z qo‘lingizda ✦','Xarajatlaringizni boshqaring. Orzularingizga yaqinlashing.'],transactions:['Har bir so‘m hisobda','Kirim, xarajat va barcha amaliyotlaringiz — bir joyda.'],family:['Bir oila. Umumiy maqsad.','Birgalikda rejalashtiring, oylik xarajatlarni nazorat qiling.'],goals:['Orzular reja bilan boshlanadi','Kichik jamg‘armalarni katta imkoniyatlarga aylantiring.'],debts:['Hisob ochiq, ko‘ngil xotirjam','Qarzlarni tartib bilan boshqaring, muddatlarni unutmang.'],bills:['Muhim sanalar yodingizda','Doimiy to‘lovlar va obunalarni oldindan rejalashtiring.'],report:['Raqamlar ortidagi manzara','Pulingiz qayerga ketayotganini tushunarli ko‘ring.'],wallets:['Pulingiz qayerda?','Naqd pul, kartalar va hamyonlar orasidagi o‘tkazmalar.'],calendar:['Muhim sanalar bir joyda','To‘lovlar, qarzlar va maqsadlaringizni taqvimda kuzating.'],utilities:['Uyingiz hisoblari nazoratda','Kommunal abonent hisoblari va rasmiy to‘lov ulanishlari.'],settings:['Sizga mos Baraka','Shaxsiy makon, ko‘rinish va ma’lumotlarni boshqarish.']};
function applySettings(){document.body.dataset.theme=state.settings.theme;document.body.classList.toggle('privacy',state.settings.privacy);document.body.classList.toggle('no-motion',!state.settings.motion);$('#theme-btn').dataset.icon=state.settings.theme==='dark'?'sun':'moon';$('#theme-btn').innerHTML=icon($('#theme-btn').dataset.icon);$('#privacy-btn').setAttribute('aria-pressed',String(state.settings.privacy));$('#privacy-btn').setAttribute('aria-label',state.settings.privacy?'Summalarni ko‘rsatish':'Summalarni yashirish');$('#workspace-name').textContent=state.settings.name;$('#profile-name').textContent=state.settings.name;$('#profile-letter').textContent=state.settings.name[0]||'O'}
function persist(){try{localStorage.setItem('baraka-preferences',JSON.stringify({theme:state.settings.theme,privacy:state.settings.privacy,motion:state.settings.motion}));if(globalThis.barakaCloud?.user)globalThis.barakaCloud.changed(state);else localStorage.setItem('baraka-v1',JSON.stringify(state));storageOK=true;return true}catch{storageOK=false;return false}}
function save(message='Saqlandi ✓'){const ok=persist();render();if(message)toast(ok?message:'Brauzerga saqlab bo‘lmadi. Sozlamalardan zaxira nusxa yuklab oling.');return ok}
function toast(message,undo){clearTimeout(toastTimer);undoAction=undo||null;$('#toast').textContent=message;if(undo){const b=document.createElement('button');b.textContent='Qaytarish';b.onclick=()=>{const action=undoAction;undoAction=null;action?.();$('#toast').style.display='none'};$('#toast').append(b)}$('#toast').style.display='flex';toastTimer=setTimeout(()=>{$('#toast').style.display='none';undoAction=null},undo?9000:4500)}
function toggleTheme(){state.settings.theme=state.settings.theme==='dark'?'light':'dark';save('')}
function togglePrivacy(){state.settings.privacy=!state.settings.privacy;save('')}
function toggleMotion(){state.settings.motion=!state.settings.motion;save('')}
const actualTransactions=()=>state.transactions.filter(t=>t.date<=day());
function totals(ts=null){const all=ts===null;ts=ts||actualTransactions();const income=sum(ts.filter(t=>t.type==='income')),expense=sum(ts.filter(t=>t.type==='expense'));return{income,expense,balance:income-expense+(all?(state.wallets||[]).reduce((s,w)=>s+w.opening,0):0),saved:state.goals.reduce((s,g)=>s+g.saved,0)}}
const monthTransactions=()=>actualTransactions().filter(t=>t.date.slice(0,7)===day().slice(0,7));
const monthExpense=()=>sum(monthTransactions().filter(t=>t.type==='expense'));
const categoryExpense=c=>sum(monthTransactions().filter(t=>t.type==='expense'&&t.category===c));
const remainingDebt=d=>Math.max(0,d.amount-(d.repaid||0));
function debtStatus(d){return remainingDebt(d)===0?'<span class="badge good">Qaytarilgan</span>':d.date<day()?'<span class="badge bad">Muddati o‘tgan</span>':daysBetween(day(),d.date)<=7?'<span class="badge warn">Yaqinlashmoqda</span>':'<span class="badge">Jarayonda</span>'}
function reminders(){let r=[];state.debts.filter(d=>remainingDebt(d)>0&&daysBetween(day(),d.date)<=7).forEach(d=>r.push({emoji:'🤝',title:`${d.name}: ${d.type==='lent'?'olinadigan':'beriladigan'} qarz`,text:`${money(remainingDebt(d))} so‘m · ${prettyDate(d.date)}${d.date<day()?' · Muddati o‘tgan':''}`,page:'debts'}));state.bills.filter(b=>!b.done&&daysBetween(day(),b.date)<=7).forEach(b=>r.push({emoji:'🗓️',title:b.name,text:`${money(b.amount)} so‘m · ${prettyDate(b.date)}${b.date<day()?' · Muddati o‘tgan':''}`,page:'bills'}));BarakaData.budgetAlerts(state,day()).forEach(a=>r.push({emoji:'⚠️',title:a.name+' · '+a.percent+'% sarflandi',text:money(a.spent)+' / '+money(a.limit)+' so‘m. '+(a.level==='limit'?'Limitga yetildi yoki oshdi.':'Budjetning kamida 80% qismi sarflandi.'),page:'family'}));for(const item of [...(state.tasks||[]).map(x=>({...x,label:'Vazifa'})),...(state.appointments||[]).map(x=>({...x,label:'Uchrashuv / eslatma'}))])if(!item.done&&daysBetween(day(),item.date)<=7)r.push({emoji:'🗓️',title:item.name,text:item.label+' · '+prettyDate(item.date)+(item.time?' · '+item.time:''),page:'tasks'});return r}
function empty(title,description='',action=''){return `<div class="empty"><span class="empty-icon">✧</span>${title}${description?`<p>${description}</p>`:''}${action}</div>`}
function editButtons(list,id){return `<div class="row-buttons"><button class="icon-button" onclick="openForm('${list}','${id}')" aria-label="Tahrirlash" title="Tahrirlash">${icon('edit')}</button><button class="icon-button" onclick="removeItem('${list}','${id}')" aria-label="O‘chirish" title="O‘chirish">${icon('trash')}</button></div>`}
function transactionRow(t){return `<div class="row"><div class="row-icon ${t.type==='income'?'positive':''}">${t.type==='income'?icon('down'):cats[t.category][0]}</div><div class="row-info"><b data-no-translate>${esc(t.name)}</b><small>${esc(t.category)} · ${esc(t.member)} · ${prettyDate(t.date)}${t.date>day()?' · Rejalashtirilgan':''}</small></div><div class="row-amount ${t.type==='income'?'positive':''}">${t.type==='income'?'+':'−'}${cash(t.amount)}<small>so‘m · ${esc(t.method||'Karta')}</small></div>${editButtons('transaction',t.id)}</div>`}
function reportRange(){if(reportPeriod==='month'){const d=new Date();d.setDate(1);return{start:dateKey(d),end:day(),length:new Date().getDate()}}if(reportPeriod==='lastmonth'){const start=new Date();start.setDate(1);start.setMonth(start.getMonth()-1);const end=new Date();end.setDate(0);return{start:dateKey(start),end:dateKey(end),length:end.getDate()}}return{start:shiftDay(-6),end:day(),length:7}}
function periodTransactions(){const r=reportRange();return state.transactions.filter(t=>t.date>=r.start&&t.date<=r.end)}
function chartHTML(start=shiftDay(-6),end=day()){
 const count=daysBetween(start,end)+1,buckets=[],group=count>10?Math.ceil(count/7):1;
 for(let i=0;i<count;i+=group){const d=new Date(start+'T12:00:00');d.setDate(d.getDate()+i);const a=dateKey(d);const last=new Date(d);last.setDate(last.getDate()+Math.min(group-1,count-i-1));const b=dateKey(last);const ts=state.transactions.filter(t=>t.date>=a&&t.date<=b);buckets.push({label:count<=7?['Yak','Du','Se','Chor','Pay','Ju','Sha'][d.getDay()]:`${d.getDate()}${group>1?'–'+last.getDate():''}`,income:sum(ts.filter(t=>t.type==='income')),expense:sum(ts.filter(t=>t.type==='expense'))})}
 const max=Math.max(1,...buckets.flatMap(b=>[b.income,b.expense]));const fmt=n=>n>=1e6?(n/1e6).toFixed(n%1e6?1:0)+' mln':n>=1000?Math.round(n/1000)+' ming':Math.round(n);
 return `<div class="chart-legend"><span><i></i>Kirim</span><span><i></i>Xarajat</span><b>${prettyDate(start)} — ${prettyDate(end)}</b></div><div class="chart-wrap" role="img" aria-label="Kirim va xarajatlar diagrammasi"><div class="chart-scale"><span>${fmt(max)}</span><span>${fmt(max*2/3)}</span><span>${fmt(max/3)}</span><span>0</span></div><div class="chart">${buckets.map((b,i)=>`<div class="bar-group" tabindex="0" aria-label="${b.label}: kirim ${money(b.income)}, xarajat ${money(b.expense)} so‘m" title="${state.settings.privacy?'Summalar yashirilgan':b.label+': kirim '+money(b.income)+' · xarajat '+money(b.expense)+' so‘m'}"><div class="bar" style="height:${b.income/max*100}%;--i:${i}"></div><div class="bar alt" style="height:${b.expense/max*100}%;--i:${i}"></div><label>${b.label}</label></div>`).join('')}</div></div>`
}
function categoriesHTML(ts=monthTransactions()){
 const values=Object.entries(cats).map(([name,[,color]])=>({name,color,value:sum(ts.filter(t=>t.type==='expense'&&t.category===name))})).filter(v=>v.value).sort((a,b)=>b.value-a.value),total=values.reduce((s,v)=>s+v.value,0);let pos=0;const gradient=values.map(v=>{let start=pos;pos+=v.value/total*100;return `${v.color} ${start}% ${pos}%`}).join(',');
 return `<div class="category-body"><div class="donut" style="background:${total?'conic-gradient('+gradient+')':'var(--line)'}"><div>Jami xarajat<b>${cash(total)}</b>so‘m</div></div><div class="category-list">${values.map(v=>`<div class="category-row" title="${esc(v.name)}${state.settings.privacy?'':': '+money(v.value)+' so‘m'}"><i style="background:${v.color}"></i>${esc(v.name)}<b>${Math.round(v.value/total*100)}%</b></div>`).join('')||'<p class="section-text">Bu davrda xarajatlar yo‘q.</p>'}</div></div>`
}
function compactGoals(){return state.goals.slice(0,3).map(g=>{let p=Math.min(100,Math.round(g.saved/g.target*100));return `<div class="goal"><div class="goal-top"><span class="row-icon">${g.icon}</span><b data-no-translate>${esc(g.name)}</b><span class="goal-percent">${p}%</span><button class="text-button" onclick="openForm('deposit','${g.id}')" aria-label="${esc(g.name)} uchun pul qo‘shish">${icon('plus')}</button></div><div class="progress" role="progressbar" aria-label="${esc(g.name)}" aria-valuenow="${p}" aria-valuemin="0" aria-valuemax="100"><div style="width:${p}%"></div></div><div class="goal-bottom"><b>${cash(g.saved)} so‘m</b><span>${cash(g.target)} so‘m</span></div></div>`}).join('')||empty('Birinchi orzuingizni rejalashtiring','Telefon, ta’til yoki yangi uy?','<button class="text-button" onclick="openForm(\'goal\')">＋ Maqsad yaratish</button>')}
function budgetBanner(){const alerts=BarakaData.budgetAlerts(state,day());return alerts.length?`<section class="insight-banner" role="status"><div><b>⚠️ Budjet ogohlantirishi</b>${alerts.map(a=>`<p>${esc(a.name)}: ${a.percent}% · ${cash(a.spent)} / ${cash(a.limit)} so‘m. ${a.level==='limit'?'Limitga yetildi yoki oshdi.':'Xarajatlarni reja bilan davom ettiring.'}</p>`).join('')}<a href="#family">Budjetni ko‘rish →</a></div></section>`:''}
function home(){const t=totals(),m=totals(monthTransactions()),bills=state.bills.filter(b=>!b.done),spent=monthExpense(),budgetLeft=state.budget-spent;
 return `<div class="hero"><section class="balance-card" id="balance-card"><div class="balance-label">${icon('wallet')} Sizning umumiy balansingiz</div><div class="balance-value">${cash(t.balance)}<small>so‘m</small></div><div class="balance-sub">Boshlang‘ich qoldiq + kirim − xarajat</div><div class="scene" aria-hidden="true"><span class="spark">✦</span><span class="spark two">✧</span><div class="coin-shadow"></div><div class="coin-float"><div class="coin-face back"></div><div class="coin-face">✳</div></div></div><div class="balance-bottom"><span class="currency-chip">UZS</span><span>Kelajagingizga ishonch bilan.</span><a href="#transactions">Amaliyotlarni ko‘rish ${icon('arrow')}</a></div></section><div class="hero-summary">${[['Shu oydagi kirim',m.income,'down','Mehnatingizning samarasi'],['Shu oydagi xarajat',m.expense,'up',monthTransactions().filter(t=>t.type==='expense').length+' ta amaliyot'],['Jami jamg‘arma',t.saved,'target',state.goals.length+' ta maqsad sari'],['Oylik budjet qoldig‘i',budgetLeft,'chart',state.budget?'Belgilangan limit asosida':'Avval budjetni belgilang']].map(([label,value,symbol,foot])=>`<section class="mini-stat"><div class="stat-top"><span>${label}</span><span class="stat-symbol">${icon(symbol)}</span></div><div class="mini-value ${value<0?'negative':''}">${cash(value)}<small>so‘m</small></div><small>${foot}</small></section>`).join('')}</div></div>
 <div class="quick-actions"><span class="quick-label">TEZKOR AMALLAR</span><button class="quick-action" onclick="quickTransaction('Oziq-ovqat')">🥑 Bozorlik</button><button class="quick-action" onclick="quickTransaction('Transport')">🚕 Transport</button><button class="quick-action" onclick="openForm('transaction',null,'income')">${icon('down')} Kirim</button><button class="quick-action" onclick="openForm('goal')">${icon('target')} Maqsad</button><button class="quick-action" onclick="openCalculator()">${icon('calculator')} Hisoblash</button></div>
 <div class="grid"><section class="card"><div class="card-head"><div><h2>Pulingiz harakati</h2><p>Kichik raqamlarda katta manzara</p></div><a class="period-chip" href="#report">Oxirgi 7 kun ↗</a></div>${chartHTML()}<div class="chart-note">✧ <span>${m.income>0?`Bu oy kirimning <strong>${Math.round(m.expense/m.income*100)}%</strong> qismi sarflangan.`:'Muntazam qayd etilgan xarajatlar rejalaringizni aniqroq qiladi.'}</span></div></section><section class="card"><div class="card-head"><div><h2>Xarajatlar tarkibi</h2><p>Pulingiz nimalarga sarflanmoqda?</p></div><span class="period-chip">Shu oy</span></div>${categoriesHTML()}</section></div>
 <div class="grid"><section class="card compact-rows"><div class="card-head"><h2>So‘nggi amaliyotlar</h2><a class="text-button" href="#transactions">Barchasi ${icon('arrow')}</a></div>${[...state.transactions].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4).map(transactionRow).join('')||empty('Hali amaliyot yo‘q','Birinchi kirim yoki xarajatingizni qo‘shing.')}</section><section class="card"><div class="card-head"><h2>Orzularingizga yaqinroq</h2><a class="text-button" href="#goals">Barchasi ${icon('arrow')}</a></div>${compactGoals()}</section></div>
 <div class="insight-banner"><div class="insight-icon">${icon(bills.length?'calendar':'spark')}</div><div><b>${bills.length?`${bills.length} ta rejalashtirilgan to‘lovingiz bor`:'Birgalikda rejalashtirish — farovonlik boshlanishi.'}</b><p>${bills.length?'To‘lovlarni oldindan ko‘rib, oy davomida xotirjam bo‘ling.':'Oila a’zolarini qo‘shing va umumiy budjetingizni belgilang.'}</p></div><a class="text-button" href="#${bills.length?'bills':'family'}">${bills.length?'To‘lovlarni ko‘rish':'Oila budjetiga o‘tish'} ${icon('arrow')}</a></div>`
}
function transactionsPage(){return `<section class="card"><div class="card-head"><div><h2>Barcha amaliyotlar</h2><p>Qidirish, saralash va tahrirlash</p></div><button class="secondary" onclick="exportTransactions()">${icon('download')} CSV</button></div><div class="filters"><div class="search-box">${icon('search')}<input id="search" type="search" placeholder="Nomi, toifa yoki a’zo…" aria-label="Amaliyotlarni qidirish" oninput="filterRows()"></div><select id="type-filter" aria-label="Amaliyot turi" onchange="filterRows()"><option value="all">Barcha turlar</option><option value="expense">Xarajatlar</option><option value="income">Kirimlar</option></select><select id="member-filter" aria-label="Oila a’zosi" onchange="filterRows()"><option value="all">Barcha a’zolar</option>${state.members.map(m=>`<option>${esc(m)}</option>`).join('')}</select><select id="sort-filter" aria-label="Saralash" onchange="filterRows()"><option value="new">Yangi avval</option><option value="old">Eski avval</option><option value="large">Katta summa avval</option></select></div><div class="filters filter-dates"><label for="from-date">Sana oralig‘i</label><input type="date" id="from-date" aria-label="Boshlanish sanasi" onchange="filterRows()"><span>—</span><input type="date" id="to-date" aria-label="Tugash sanasi" onchange="filterRows()"><button class="text-button" onclick="resetFilters()">Tozalash</button></div><div id="list-summary" class="list-summary"></div><div id="transaction-list"></div><div id="list-pagination"></div></section>`}
let visibleLimit=50;
function filteredTransactions(){const q=($('#search')?.value||'').toLocaleLowerCase(),type=$('#type-filter')?.value||'all',member=$('#member-filter')?.value||'all',from=$('#from-date')?.value||'',to=$('#to-date')?.value||'',sort=$('#sort-filter')?.value||'new';return [...state.transactions].filter(t=>([t.name,t.category,t.member].join(' ').toLocaleLowerCase().includes(q))&&(type==='all'||t.type===type)&&(member==='all'||t.member===member)&&(!from||t.date>=from)&&(!to||t.date<=to)).sort((a,b)=>sort==='large'?b.amount-a.amount:sort==='old'?a.date.localeCompare(b.date):b.date.localeCompare(a.date))}
function filterRows(more=false){if(!more)visibleLimit=50;const ts=filteredTransactions(),t=totals(ts);$('#transaction-list').innerHTML=ts.slice(0,visibleLimit).map(transactionRow).join('')||empty('Amaliyot topilmadi','Filtrlarni o‘zgartiring yoki yangi yozuv kiriting.');$('#list-summary').innerHTML=`<span>${ts.length} ta amaliyot</span><span>Kirim: <b class="positive">${cash(t.income)}</b> · Xarajat: <b>${cash(t.expense)}</b> so‘m</span>`;$('#list-pagination').innerHTML=ts.length>visibleLimit?`<button class="secondary section-gap" onclick="visibleLimit+=50;filterRows(true)">Yana ko‘rsatish (${ts.length-visibleLimit})</button>`:''}
function resetFilters(){['search','from-date','to-date'].forEach(s=>$('#'+s).value='');$('#type-filter').value='all';$('#member-filter').value='all';$('#sort-filter').value='new';filterRows()}
function familyPage(){const expense=monthExpense(),p=state.budget?Math.min(100,expense/state.budget*100):0;return `${globalThis.barakaCloud?.familyPanel?.()||''}<div class="grid equal-grid"><section class="card"><div class="card-head"><div><h2>Oylik oila budjeti</h2><p>${new Date().toLocaleDateString('uz-UZ',{month:'long',year:'numeric'})}</p></div><button class="text-button" onclick="openForm('budget')">${icon('edit')} Belgilash</button></div><small>Oila uchun ajratilgan limit</small><div class="big-value">${cash(state.budget)} <small>so‘m</small></div><div class="progress ${expense>state.budget&&state.budget?'over':''}"><div style="width:${p}%"></div></div><div class="metric-pair"><div><small>Sarflandi</small><b>${cash(expense)} so‘m</b></div><div><small>Qoldiq</small><b class="${state.budget-expense<0?'negative':'positive'}">${cash(state.budget-expense)} so‘m</b></div></div><div class="chart-note">${!state.budget?'✧ Oylik budjetni belgilang va xarajatlaringizni nazorat qiling.':expense>state.budget?'Limitdan oshdingiz. Toifalar bo‘yicha sarflarni ko‘rib chiqing.':`Budjetning ${Math.round(p)}% qismi sarflandi. ${daysBetween(day(),dateKey(new Date(new Date().getFullYear(),new Date().getMonth()+1,0)))+1} kun uchun rejalashtiring.`}</div></section><section class="card"><div class="card-head"><div><h2>Oila a’zolari</h2><p>Shu oy xarajatlari</p></div><button class="text-button" onclick="openForm('member')">${icon('plus')} A’zo</button></div>${state.members.map((m,i)=>`<div class="member"><span class="avatar" style="background:${i%2?'var(--surface2)':'var(--mint)'}">${esc(m[0])}</span><div class="member-text"><b data-no-translate>${esc(m)}</b><small>${i===0?'Hisob egasi':'Oila a’zosi'}</small></div><span>${cash(sum(monthTransactions().filter(t=>t.type==='expense'&&t.member===m)))} <small>so‘m</small></span></div>`).join('')}</section></div><section class="card"><div class="card-head"><div><h2>Toifalar bo‘yicha limitlar</h2><p>Har bir yo‘nalish uchun oylik chegara</p></div><button class="secondary" onclick="openForm('limit')">${icon('plus')} Limit qo‘shish</button></div><div class="limits-grid">${Object.entries(state.limits).filter(([,v])=>v>0).map(([c,limit])=>{const spent=categoryExpense(c);return `<div class="limit-card"><div class="limit-top"><b>${cats[c][0]} ${esc(c)}</b><button class="text-button" onclick="openForm('limit',null,'${esc(c)}')">${icon('edit')}</button></div><div class="progress ${spent>limit?'over':''}"><div style="width:${Math.min(100,spent/limit*100)}%"></div></div><div class="goal-bottom"><b>${cash(spent)} so‘m</b><span>${cash(limit)} so‘m</span></div><p>${spent>limit?'Limit '+cash(spent-limit)+' so‘mga oshgan':cash(limit-spent)+' so‘m qoldi'}</p></div>`}).join('')||empty('Hali limitlar belgilanmagan','Oziq-ovqat, transport yoki xaridlar uchun limit kiriting.')}</div></section><div class="insight-banner"><div class="insight-icon">${icon('users')}</div><div><b>Mahalliy hisob va serverdagi oila</b><p>Amaliyotni oila a’zosi nomidan kiriting. Hisobga kiring va oila taklif kodi orqali bir serverdagi umumiy budjetga ulaning. Internet orqali foydalanish uchun server HTTPS domenida joylashtiriladi.</p></div></div>`}
function goalsPage(){return `<div class="card-head"><p class="section-text">${state.goals.length} ta maqsad · Jamg‘arma: ${cash(totals().saved)} so‘m</p><button class="primary" onclick="openForm('goal')">${icon('plus')} Yangi maqsad</button></div><div class="triple-grid">${state.goals.map(g=>{const remaining=Math.max(0,g.target-g.saved),p=Math.min(100,Math.round(g.saved/g.target*100)),months=g.date?Math.max(1,Math.ceil(daysBetween(day(),g.date)/30)):0;return `<section class="card goal-card"><div class="goal-visual"><span class="goal-emoji">${g.icon}</span><span class="badge ${p===100?'good':''}">${p===100?'✓ Maqsadga yetdingiz':p+'% bajarildi'}</span></div><h2>${esc(g.name)}</h2><p class="goal-meta">${g.date?'Maqsad sanasi: '+prettyDate(g.date):'Maqsad sanasi belgilanmagan'}</p><div class="progress"><div style="width:${p}%"></div></div><div class="goal-bottom"><b>${cash(g.saved)}</b><span>${cash(g.target)} so‘m</span></div><div class="goal-tip">${remaining===0?'Ajoyib! Mehnatingiz o‘z samarasini berdi. ✦':g.date&&g.date<day()?'Maqsad sanasi o‘tgan. Rejangizni yangilashingiz mumkin.':months?`Oyiga ${cash(Math.ceil(remaining/months))} so‘mdan ajratsangiz, maqsadga yaqinlashasiz.`:`Yana ${cash(remaining)} so‘m jamg‘arish kerak.`}</div><div class="goal-actions"><button class="primary" onclick="openForm('deposit','${g.id}')">${icon('plus')} Pul qo‘shish</button><button class="secondary" onclick="openForm('goal','${g.id}')" aria-label="Maqsadni tahrirlash">${icon('edit')}</button><button class="secondary" onclick="removeItem('goal','${g.id}')" aria-label="Maqsadni o‘chirish">${icon('trash')}</button></div></section>`}).join('')}</div>${state.goals.length?'':`<section class="card">${empty('Sizning birinchi orzuingiz nima?','Telefon, uy, ta’til yoki ta’lim — birinchi maqsadni yarating.','<button class="primary" onclick="openForm(\'goal\')">＋ Maqsad yaratish</button>')}</section>`}<div class="insight-banner"><div class="insight-icon">${icon('target')}</div><div><b>Jamg‘arma alohida hisobga olinadi</b><p>Maqsadga ajratilgan summa umumiy balansdan avtomatik ayrilmaydi. Haqiqiy xaridni amaliyot sifatida qayd eting.</p></div><button class="text-button" onclick="openCalculator()">Kalkulyator ${icon('arrow')}</button></div>`}
function debtsPage(){const lent=state.debts.filter(d=>d.type==='lent').reduce((s,d)=>s+remainingDebt(d),0),borrowed=state.debts.filter(d=>d.type==='borrowed').reduce((s,d)=>s+remainingDebt(d),0);return `<div class="grid equal-grid"><div class="debt-total"><small>Men berganman · olinadigan</small><b class="positive">${cash(lent)} <small>so‘m</small></b></div><div class="debt-total"><small>Men olganman · qaytariladigan</small><b>${cash(borrowed)} <small>so‘m</small></b></div></div><section class="card"><div class="card-head"><h2>Qarzlar daftari</h2><button class="primary" onclick="openForm('debt')">${icon('plus')} Qarz qo‘shish</button></div>${[...state.debts].sort((a,b)=>(remainingDebt(a)===0)-(remainingDebt(b)===0)||a.date.localeCompare(b.date)).map(d=>`<div class="debt-card"><div class="debt-top"><span class="avatar">${esc(d.name[0])}</span><div class="row-info"><b data-no-translate>${esc(d.name)}</b><small>${d.type==='lent'?'Men qarz berganman':'Men qarz olganman'} · ${prettyDate(d.date)}</small></div><div class="row-amount">${cash(remainingDebt(d))}<small>so‘m qoldi</small></div>${editButtons('debt',d.id)}</div><div class="debt-detail"><span>${debtStatus(d)} ${d.repaid?' · Qaytarildi: '+cash(d.repaid)+' so‘m':''}</span>${remainingDebt(d)>0?`<button class="secondary" onclick="openForm('repay','${d.id}')">Qaytarishni qayd etish</button>`:''}</div></div>`).join('')||empty('Hozircha qarzlar yo‘q','Hisob ochiq, ko‘ngil xotirjam.')}<div class="form-note">Qarzlar alohida daftarda saqlanadi. Qarz berish, olish va qaytarish umumiy balansni avtomatik o‘zgartirmaydi; pul harakatini amaliyot sifatida ham kiriting.</div></section>`}
function billsPage(){const upcoming=state.bills.filter(b=>!b.done).sort((a,b)=>a.date.localeCompare(b.date)),due=upcoming.filter(b=>b.date<=shiftDay(30));return `<div class="grid equal-grid"><div class="debt-total"><small>Kelgusi 30 kunlik to‘lovlar</small><b>${cash(sum(due))}<small>so‘m · ${due.length} ta to‘lov</small></b></div><div class="debt-total"><small>Oylik doimiy to‘lovlar</small><b>${cash(sum(state.bills.filter(b=>b.frequency==='monthly')))}<small>so‘m / oy</small></b></div></div><section class="card"><div class="card-head"><div><h2>To‘lovlar va obunalar</h2><p>Internet, ijara, kurslar va boshqa rejalar</p></div><button class="primary" onclick="openForm('bill')">${icon('plus')} Qo‘shish</button></div>${[...upcoming,...state.bills.filter(b=>b.done)].map(b=>`<div class="bill-item"><div class="row-icon">${cats[b.category][0]}</div><div class="row-info"><b data-no-translate>${esc(b.name)}</b><small>${prettyDate(b.date)} · ${b.frequency==='monthly'?'Har oy':'Bir martalik'}</small><span class="badge ${b.done?'good':b.date<day()?'bad':daysBetween(day(),b.date)<=7?'warn':''}">${b.done?'✓ To‘langan':b.date<day()?'Muddati o‘tgan':daysBetween(day(),b.date)===0?'Bugun':daysBetween(day(),b.date)+' kundan so‘ng'}</span></div><strong>${cash(b.amount)}<small>so‘m</small></strong><div class="bill-actions">${!b.done?`<button class="secondary" onclick="confirmBill('${b.id}')">${icon('check')} To‘lash</button>`:''}<button class="icon-button" onclick="openForm('bill','${b.id}')" aria-label="To‘lovni tahrirlash">${icon('edit')}</button><button class="icon-button" onclick="removeItem('bill','${b.id}')" aria-label="To‘lovni o‘chirish">${icon('trash')}</button></div></div>`).join('')||empty('Muhim to‘lovlarni rejalashtiring','To‘lov qo‘shing, keyingi sanani Baraka bilan kuzating.')}<div class="form-note">“To‘lash” tasdiqlanganda xarajat yaratiladi. Oylik to‘lov sanasi keyingi oyga o‘tadi. Eslatmalar sayt ichida ko‘rinadi; yopiq sayt telefoningizga bildirishnoma yubormaydi.</div></section>`}
function reportPage(){const ts=periodTransactions(),t=totals(ts),range=reportRange(),rate=t.income?Math.round((t.income-t.expense)/t.income*100):0,top=Object.keys(cats).map(c=>({name:c,amount:sum(ts.filter(t=>t.type==='expense'&&t.category===c))})).sort((a,b)=>b.amount-a.amount)[0];return `<div class="card-head"><div><select class="select-control" id="report-period" aria-label="Hisobot davri" onchange="reportPeriod=this.value;render()"><option value="week" ${reportPeriod==='week'?'selected':''}>Oxirgi 7 kun</option><option value="month" ${reportPeriod==='month'?'selected':''}>Shu oy</option><option value="lastmonth" ${reportPeriod==='lastmonth'?'selected':''}>O‘tgan oy</option></select></div><div class="settings-actions"><button class="secondary" onclick="exportReport()">${icon('download')} CSV</button><button class="secondary" onclick="window.print()">${icon('print')} Chop etish</button></div></div><p class="section-text">${prettyDate(range.start)} — ${prettyDate(range.end)}</p><div class="report-stats">${[['Jami kirim',t.income,'Kirim amaliyotlari'],['Jami xarajat',t.expense,ts.filter(t=>t.type==='expense').length+' ta xarajat'],['Davr qoldig‘i',t.balance,'Kirim va xarajat farqi'],['Kunlik o‘rtacha',t.expense/range.length,'Xarajat / '+range.length+' kun']].map(([label,value,foot],i)=>`<div class="report-stat ${i===2?'highlight':''}"><small>${label}</small><b>${cash(value)}</b><em>so‘m · ${foot}</em></div>`).join('')}</div><div class="grid"><section class="card"><div class="card-head"><div><h2>Davr bo‘yicha pul harakati</h2><p>Har bir ustun davrdagi kirim va xarajatni ko‘rsatadi</p></div></div>${chartHTML(range.start,range.end)}<div class="chart-note">${t.expense>t.income?'Bu davrda xarajatlar kirimdan oshgan. Toifalar bo‘yicha sarflarni ko‘rib chiqing.':t.income?'Kirimning '+rate+'% qismi qoldi. Bu raqam amaldagi jamg‘arma o‘tkazmalari bilan teng bo‘lishi shart emas.':'Hisobot uchun birinchi amaliyotingizni qo‘shing.'}</div></section><section class="card"><div class="card-head"><div><h2>Xarajat yo‘nalishlari</h2><p>Tanlangan davr bo‘yicha</p></div></div>${categoriesHTML(ts)}</section></div><section class="card"><div class="card-head"><h2>Davrning qisqa xulosasi</h2><span class="badge">${ts.length} ta amaliyot</span></div><div class="limits-grid"><div class="limit-card"><small>Eng katta xarajat toifasi</small><div class="big-value" style="font-size:21px">${top.amount?cats[top.name][0]+' '+top.name:'Hali yo‘q'}</div><p>${top.amount?cash(top.amount)+' so‘m':'Xarajatlar kiritilganda ko‘rinadi.'}</p></div><div class="limit-card"><small>Davrdagi eng katta xarajat</small><div class="big-value" style="font-size:21px">${cash(Math.max(0,...ts.filter(t=>t.type==='expense').map(t=>t.amount)))} <small>so‘m</small></div><p>Kundalik odatlarni kuzatish rejangizga aniqlik kiritadi.</p></div></div></section>`}
function settingsPage(){return `${globalThis.barakaCloud?.accountPanel?.()||''}<div class="grid equal-grid"><section class="card"><div class="card-head"><h2>Shaxsiy makon</h2>${icon('users')}</div><div class="settings-row"><div><h3>${esc(state.settings.name)}</h3><p>Oilangiz yoki shaxsiy hisobingiz nomi</p></div><button class="secondary" onclick="openForm('profile')">${icon('edit')} Tahrirlash</button></div><div class="settings-row"><div><h3>Tungi rejim</h3><p>Ko‘zga qulay, sokin ranglar</p></div><button class="switch ${state.settings.theme==='dark'?'on':''}" role="switch" aria-checked="${state.settings.theme==='dark'}" aria-label="Tungi rejim" onclick="toggleTheme()"></button></div><div class="settings-row"><div><h3>Summalarni yashirish</h3><p>Yoningizdagilarga raqamlar ko‘rinmasin</p></div><button class="switch ${state.settings.privacy?'on':''}" role="switch" aria-checked="${state.settings.privacy}" aria-label="Summalarni yashirish" onclick="togglePrivacy()"></button></div><div class="settings-row"><div><h3>Animatsiya va 3D</h3><p>Jonli diagrammalar, tanga va yengil harakatlar. Qurilmaning kamaytirilgan harakat sozlamasi ham hisobga olinadi.</p></div><button class="switch ${state.settings.motion?'on':''}" role="switch" aria-checked="${state.settings.motion}" aria-label="Animatsiyalar" onclick="toggleMotion()"></button></div><div class="settings-row"><div><h3>Jamg‘arma kalkulyatori</h3><p>Maqsadingiz uchun qancha vaqt kerakligini hisoblang</p></div><button class="secondary" onclick="openCalculator()">Ochish ↗</button></div></section><section class="card"><div class="card-head"><h2>Ma’lumotlaringiz sizniki</h2>${icon('wallet')}</div><div class="backup-box"><h3>Zaxira nusxa</h3><p>Amaliyotlar, maqsadlar, qarzlar, limitlar va sozlamalarni bitta JSON faylga yuklab oling. Brauzer ma’lumotlarini tozalashdan oldin nusxa saqlang.</p><div class="settings-actions"><button class="primary" onclick="exportBackup()">${icon('download')} Nusxa olish</button><button class="secondary" onclick="$('#import-file').click()">${icon('upload')} Tiklash</button></div></div><div class="settings-row"><div><h3>Saqlash holati</h3><p>${globalThis.barakaCloud?.user?'Server hisobi faol; yuqoridagi sinxronlash holatini kuzating.':storageOK?'Ma’lumotlar shu brauzerda saqlanmoqda.':'Brauzerga saqlashda muammo bor. Zaxira nusxa oling.'} Hisobga kirilsa server nusxasi bilan sinxronlanadi.</p></div><span class="badge ${storageOK?'good':'bad'}">${globalThis.barakaCloud?.user?'Server':storageOK?'Mahalliy':'Tekshiring'}</span></div><div class="settings-row"><div><h3>Amaliyotlar eksporti</h3><p>Barcha yozuvlarni Excel uchun CSV formatida oling</p></div><button class="secondary" onclick="downloadCSV(state.transactions,'baraka-barcha-amaliyotlar.csv')">${icon('download')} CSV</button></div><div class="settings-row"><div><h3>Hisobni tozalash</h3><p>Avval zaxira nusxa olishni tavsiya qilamiz. Tasdiq so‘raladi.</p></div><button class="danger-button" onclick="resetAccount()">Tozalash</button></div></section></div><div class="insight-banner"><div class="insight-icon">${icon('spark')}</div><div><b>Baraka 4.0 · Kundalik hayotga qulay yordamchi</b><p>Tezkor qo‘shish: Alt + N. Qidirish: Ctrl / ⌘ + K. Valyuta: O‘zbekiston so‘mi. Bankka ulanish va avtomatik pul yechish mavjud emas.</p></div></div>`}
function render(){
 page=location.hash.slice(1)||'today';if(!Object.hasOwn(titles,page))page='today';
 if(globalThis.BarakaLife?.child()&&!['today','tasks','shopping','personal','more','settings'].includes(page))page='today';
 applySettings();const mainAdd=$('#main-add');if(mainAdd){mainAdd.hidden=['prayer','transport','more','personal','meters','seasonal','installments','remittances','shopping'].includes(page);mainAdd.style.display=mainAdd.hidden?'none':'inline-flex';mainAdd.innerHTML=icon('plus')+(['today','tasks'].includes(page)?' Reja qo‘shish':page==='favorites'?' Joy saqlash':' Amaliyot qo‘shish');mainAdd.onclick=()=>openForm(['today','tasks'].includes(page)?'day-task':page==='favorites'?'favorite':'transaction')}$('#title').textContent=titles[page][0];$('#subtitle').textContent=titles[page][1];$('#page-name').textContent=(globalThis.BarakaLife?.titles[page]?.[0])||({home:'Umumiy ko‘rinish',transactions:'Amaliyotlar',family:'Oila budjeti',goals:'Jamg‘armalar',debts:'Qarzlar',bills:'To‘lovlar',report:'Hisobotlar',settings:'Sozlamalar',wallets:'Hamyonlar',calendar:'Moliyaviy taqvim',utilities:'Kommunal xizmatlar',today:'Bugun',tasks:'Rejalar',prayer:'Namoz vaqtlari',favorites:'Saqlangan joylar',transport:'Transport'})[page];
 document.querySelectorAll('nav a').forEach(a=>{const active=a.dataset.page===page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 $('#demo-note').hidden=!state.demo;$('#demo-note').style.display=state.demo?'flex':'none';const due=reminders();$('#notification-dot').hidden=!due.length;const billsDue=state.bills.filter(b=>!b.done&&daysBetween(day(),b.date)<=7).length;$('#bill-badge').textContent=billsDue||'';
 const views={...globalThis.BarakaLife?.views,...BarakaDay.views,...BarakaFavorites.views,home,transactions:transactionsPage,family:familyPage,goals:goalsPage,debts:debtsPage,bills:billsPage,report:reportPage,settings:settingsPage,wallets:walletsPage,calendar:calendarPage,utilities:utilitiesPage};$('#view').innerHTML=(globalThis.BarakaLife&&!BarakaLife.child()&&['today','home'].includes(page)?BarakaLife.quick()+BarakaLife.runway():'')+budgetBanner()+views[page]()+ (globalThis.BarakaLife&&page==='settings'?BarakaLife.settings():'');$('#view').classList.remove('view-enter');void $('#view').offsetWidth;$('#view').classList.add('view-enter');if(page==='transactions')filterRows();paintIcons();bindTilt();globalThis.barakaCloud?.paint();BarakaDay.afterRender();globalThis.BarakaLocale?.paint();
}
function bindTilt(){const card=$('#balance-card');if(!card)return;card.onpointermove=e=>{if(!state.settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches||e.pointerType==='touch')return;const r=card.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;card.style.transform=`perspective(1100px) rotateX(${-y*4}deg) rotateY(${x*4}deg)`};card.onpointerleave=()=>{card.style.transform='';card.style.transition='transform .4s ease'};}

function field(label,name,type='text',value='',extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function select(label,name,options,value=''){return `<label class="field">${label}<select name="${name}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`}
const amountField=(label,name,value='',zero=false)=>field(label,name,'number',value,`required min="${zero?0:1}" max="1000000000000" step="1" inputmode="numeric"`);
const nameField=(label,value='',max=80)=>field(label,'name','text',value,`required maxlength="${max}" autocomplete="off"`);
const dateField=(label,value=day(),required=true)=>field(label,'date','date',value,required?'required':'');
const listMap={transaction:'transactions',goal:'goals',debt:'debts',bill:'bills'};
function setModal(title,content,submit=true){modalCanSubmit=submit;$('#modal-title').textContent=title;$('#fields').innerHTML=content;$('#form-error').textContent='';$('.modal-actions').style.display=submit?'flex':'none';$('#save-button').textContent='Saqlash ↗';if(!$('#modal').open)$('#modal').showModal();globalThis.BarakaLocale?.paint()}
function closeModal(){modalCanSubmit=false;$('#modal').close();pendingAction=null;formType=''}
function quickTransaction(category){quickPreset={category};openForm('transaction')}
function openForm(type,id=null,preset=''){
 formType=type;activeId=id;pendingAction=null;const feature=globalThis.BarakaLife?.form(type,id)||BarakaFavorites.form(type,id)||BarakaDay.form(type,id)||featureForm(type,id,preset);if(feature){setModal(feature.title,feature.html);return}const list=listMap[type];const d=(list&&id?state[list].find(t=>t.id===id):null)||{};let content='',title='';
 if(type==='transaction'){
 title=id?'Amaliyotni tahrirlash':'Yangi amaliyot';content=select('Amaliyot turi','type',[['expense','↗ Xarajat'],['income','↙ Kirim']],d.type||preset||'expense')+amountField('Summa (so‘m)','amount',d.amount??'')+`<div class="amount-presets">${[25000,50000,100000,500000].map(n=>`<button type="button" onclick="$('#fields input[name=amount]').value=${n}">${money(n)}</button>`).join('')}</div>`+nameField('Nima uchun?',d.name||'')+`<div class="form-grid">${select('Toifa','category',Object.entries(cats).map(([c,[e]])=>[c,e+' '+c]),d.category||quickPreset?.category||'Oziq-ovqat')}${select('Oila a’zosi','member',[...new Set([...state.members,...(d.member?[d.member]:[])])].map(m=>[m,m]),d.member||state.members[0])}${dateField('Sana',d.date||day())}${select('Hamyon','walletId',(state.wallets||[]).map(w=>[w.id,w.name]),d.walletId||(d.method==='Naqd'?'cash':'card'))}</div>`;quickPreset=null;
 }
 if(type==='goal'){title=id?'Maqsadni tahrirlash':'Yangi jamg‘arma maqsadi';content=nameField('Maqsad nomi',d.name||'',60)+select('Maqsad belgisi','icon',[['🎯','🎯 Maqsad'],['📱','📱 Telefon'],['🏝️','🏝️ Ta’til'],['💍','💍 To‘y'],['🏡','🏡 Uy'],['🚗','🚗 Avtomobil'],['🎓','🎓 Ta’lim'],['🛟','🛟 Zaxira jamg‘arma']],d.icon||'🎯')+amountField('Kerakli summa (so‘m)','target',d.target??'')+amountField('Yig‘ilgan summa (so‘m)','saved',d.saved??0,true)+dateField('Maqsad sanasi (ixtiyoriy)',d.date||'',false)}
 if(type==='deposit'){const g=state.goals.find(g=>g.id===id);if(!g)return;title='Orzuingizga yana bir qadam';content=`<div class="form-note">${g.icon} <strong>${esc(g.name)}</strong><br>Yig‘ilgan: ${cash(g.saved)} / ${cash(g.target)} so‘m</div>`+select('Amal','direction',[['add','Jamg‘armaga qo‘shish'],['withdraw','Jamg‘armadan olish']])+amountField('Summa (so‘m)','amount')+'<p class="section-text">Bu amal umumiy balansni avtomatik o‘zgartirmaydi.</p>'}
 if(type==='budget'){title='Oylik budjetni belgilang';content=amountField('Oila uchun oylik limit (so‘m)','budget',state.budget||'')+'<p class="section-text">Limit har oyning joriy xarajatlari bilan solishtiriladi.</p>'}
 if(type==='member'){title='Oila a’zosini qo‘shish';content=nameField('Oila a’zosining ismi','',40)}
 if(type==='limit'){title='Toifa uchun oylik limit';content=select('Toifa','category',Object.entries(cats).map(([c,[e]])=>[c,e+' '+c]),preset)+amountField('Oylik limit (0 — o‘chirish)','limit',state.limits[preset]??'',true)}
 if(type==='debt'){title=id?'Qarzni tahrirlash':'Qarzni qayd etish';content=nameField('Kim bilan?',d.name||'',60)+select('Qarz turi','type',[['lent','Men qarz berdim'],['borrowed','Men qarz oldim']],d.type||'lent')+amountField('Jami qarz (so‘m)','amount',d.amount??'')+amountField('Qaytarilgan summa (so‘m)','repaid',d.repaid??0,true)+dateField('Qaytarish sanasi',d.date||day())}
 if(type==='repay'){const d=state.debts.find(d=>d.id===id);if(!d)return;title='Qaytarishni qayd etish';content=`<div class="form-note"><b data-no-translate>${esc(d.name)}</b> · Qolgan qarz: ${cash(remainingDebt(d))} so‘m</div>`+amountField('Qaytarilgan summa (so‘m)','amount',remainingDebt(d))+'<p class="section-text">Qisman qaytarishni ham kiritishingiz mumkin.</p>'}
 if(type==='bill'){title=id?'To‘lovni tahrirlash':'To‘lovni rejalashtirish';content=nameField('To‘lov nomi',d.name||'',60)+amountField('Summa (so‘m)','amount',d.amount??'')+`<div class="form-grid">${dateField('Keyingi to‘lov sanasi',d.date||day())}${select('Takrorlanishi','frequency',[['monthly','Har oy'],['once','Bir martalik']],d.frequency||'monthly')}</div>`+select('Xarajat toifasi','category',Object.keys(cats).map(c=>[c,c]),d.category||'Uy va kommunal')}
 if(type==='profile'){title='Makoningizga nom bering';content=nameField('Oila yoki hisob nomi',state.settings.name,40)}
 setModal(title,content);
}
function readForm(form){const d=Object.fromEntries(new FormData(form));for(const key of ['amount','target','saved','budget','limit','repaid'])if(key in d){if(d[key]==='')throw Error('Summani kiriting.');d[key]=Number(d[key]);if(!Number.isSafeInteger(d[key])||d[key]<0||d[key]>1e12||(['amount','target','budget'].includes(key)&&d[key]===0))throw Error('Summani 1 dan 1 000 000 000 000 gacha butun so‘mda kiriting.')}if('name' in d){d.name=d.name.trim();if(!d.name)throw Error('Nomini kiriting.')}if(d.date&&(!/^\d{4}-\d{2}-\d{2}$/.test(d.date)||!Number.isFinite(Date.parse(d.date+'T12:00:00'))||dateKey(new Date(d.date+'T12:00:00'))!==d.date))throw Error('Sanani to‘g‘ri kiriting.');return d}
function commitEntry(d){
 if(globalThis.BarakaLife?.commit(formType,activeId,d)||BarakaFavorites.commit(formType,activeId,d)||BarakaDay.commit(formType,activeId,d)||commitFeature(d))return;
 if(formType==='transaction'){if(!Object.hasOwn(cats,d.category)||!['income','expense'].includes(d.type))throw Error('Toifani tekshiring.');d.method=state.wallets.find(w=>w.id===d.walletId)?.type==='cash'?'Naqd':'Karta';const t={...d,id:activeId||uid()};if(activeId)state.transactions=state.transactions.map(x=>x.id===activeId?t:x);else state.transactions.push(t)}
 if(formType==='goal'){const g={...d,id:activeId||uid()};if(activeId)state.goals=state.goals.map(x=>x.id===activeId?g:x);else state.goals.push(g)}
 if(formType==='deposit'){const g=state.goals.find(g=>g.id===activeId);if(!g)throw Error('Maqsad topilmadi.');if(d.direction==='withdraw'&&d.amount>g.saved)throw Error('Yig‘ilgan summadan ko‘p olib bo‘lmaydi.');if(d.direction!=='withdraw'&&g.saved+d.amount>1e12)throw Error('Jamg‘arma summasi juda katta.');g.saved+=d.direction==='withdraw'?-d.amount:d.amount}
 if(formType==='budget')state.budget=d.budget;
 if(formType==='member'){if(state.members.length>=50)throw Error('Eng ko‘pi 50 a’zo qo‘shish mumkin.');if(state.members.some(m=>m.toLocaleLowerCase()===d.name.toLocaleLowerCase()))throw Error('Bu a’zo allaqachon qo‘shilgan.');state.members.push(d.name)}
 if(formType==='limit'){if(d.limit===0)delete state.limits[d.category];else state.limits[d.category]=d.limit}
 if(formType==='debt'){if(d.repaid>d.amount)throw Error('Qaytarilgan summa jami qarzdan katta bo‘lishi mumkin emas.');const debt={...d,id:activeId||uid(),paid:d.repaid===d.amount};if(activeId)state.debts=state.debts.map(x=>x.id===activeId?debt:x);else state.debts.push(debt)}
 if(formType==='repay'){const debt=state.debts.find(x=>x.id===activeId);if(!debt)throw Error('Qarz topilmadi.');if(d.amount>remainingDebt(debt))throw Error('Qolgan qarzdan katta summa kiritildi.');debt.repaid=(debt.repaid||0)+d.amount;debt.paid=debt.repaid===debt.amount}
 if(formType==='bill'){const old=state.bills.find(x=>x.id===activeId),bill={...d,id:activeId||uid(),anchorDay:Number(d.date.slice(-2)),done:old?.done||false,lastPaid:old?.lastPaid||''};if(activeId)state.bills=state.bills.map(x=>x.id===activeId?bill:x);else state.bills.push(bill)}
 if(formType==='profile')state.settings.name=d.name;
}
$('#entry-form').addEventListener('submit',async e=>{e.preventDefault();if(!modalCanSubmit)return;try{if(formType==='confirm'){const action=pendingAction;closeModal();action?.();return}const d=readForm(e.target);if(formType==='personal-entry'){await BarakaLife.personalSubmit(d);return}if(formType==='meter'){const modal=$('#modal'),button=$('#save-button');if(button.disabled)return;button.disabled=true;try{d.photo=await BarakaLife.photo()}finally{button.disabled=false}if(formType!=='meter'||!modal.open)return;}if(formType==='day-call'){BarakaDay.submitCall(d);return}if(formType==='utility-pay'){globalThis.barakaCloud?.payUtility(activeId,d);return}if(formType.startsWith('auth-')||formType.startsWith('family-')){globalThis.barakaCloud?.submit(d,formType);return}commitEntry(d);closeModal();save()}catch(err){$('#form-error').textContent=err.message}});
function confirmAction(title,content,action,label='Tasdiqlash'){formType='confirm';pendingAction=action;setModal(title,content);$('#save-button').textContent=label}
function removeItem(type,id){const list=listMap[type];if(!list)return;const index=state[list].findIndex(x=>x.id===id);if(index<0)return;const item=state[list][index];confirmAction('Yozuv o‘chirilsinmi?',`<p class="section-text"><b data-no-translate>${esc(item.name)}</b> o‘chiriladi. O‘chirgandan keyin ham 9 soniya ichida qaytarishingiz mumkin.</p>`,()=>{state[list]=state[list].filter(x=>x.id!==id);persist();render();toast('Yozuv o‘chirildi',()=>{state[list].splice(Math.min(index,state[list].length),0,item);save('Yozuv qaytarildi ✓')})},'O‘chirish')}
function blankState(){return{shopping:[],installments:[],remittances:[],meterReadings:[],version:4,demo:false,budget:0,members:['Men'],settings:{...state.settings},limits:{},transactions:[],goals:[],debts:[],bills:[],wallets:[{id:'cash',name:'Naqd pul',type:'cash',opening:0},{id:'card',name:'Bank kartasi',type:'card',opening:0}],transfers:[],utilities:[],tasks:[],appointments:[],savedPlaces:[]}}
function clearDemo(){confirmAction('O‘z hisobingizni boshlaysizmi?','<p class="section-text">Hozirgi namuna yozuvlari tozalanadi. Yangi kirim, xarajat va maqsadlarni o‘zingiz kiritasiz.</p>',()=>{const before=state;state=blankState();persist();render();toast('Toza hisobingiz tayyor ✓',()=>{state=before;save('Avvalgi hisob qaytarildi')})},'Boshlash')}
function resetAccount(){confirmAction('Hisob tozalansinmi?','<p class="section-text">Amaliyotlar, maqsadlar, qarzlar, to‘lovlar va limitlar o‘chiriladi. Avval zaxira nusxa oling. Ko‘rinish sozlamalaringiz saqlanadi.</p>',()=>{const before=state;state=blankState();persist();render();toast('Hisob tozalandi',()=>{state=before;save('Hisob qaytarildi')})},'Hisobni tozalash')}
function nextMonthlyDate(date,anchor){const d=new Date(date+'T12:00:00'),year=d.getFullYear(),month=d.getMonth()+1,last=new Date(year,month+1,0).getDate();return dateKey(new Date(year,month,Math.min(anchor||d.getDate(),last),12))}
function payBill(id){const b=state.bills.find(b=>b.id===id);if(!b||b.done)return;const before=JSON.stringify(state),period=b.date;state.transactions.push({id:uid(),name:b.name,amount:b.amount,type:'expense',category:b.category,member:state.members[0],method:state.wallets?.[0]?.type==='cash'?'Naqd':'Karta',walletId:state.wallets?.[0]?.id||'cash',date:day()});b.lastPaid=day();if(b.frequency==='monthly'){b.anchorDay=b.anchorDay||Number(period.slice(-2));b.date=nextMonthlyDate(period,b.anchorDay)}else b.done=true;persist();render();toast('To‘lov xarajatlarga qo‘shildi ✓',()=>{state=JSON.parse(before);save('To‘lov bekor qilindi')})}
function confirmBill(id){const b=state.bills.find(b=>b.id===id);if(!b||b.done)return;confirmAction('To‘lovni qayd etamizmi?',`<div class="form-note"><b data-no-translate>${esc(b.name)}</b><br>${cash(b.amount)} so‘m xarajat sifatida bugungi sana bilan qo‘shiladi.<br>Hamyon: ${esc(state.wallets?.[0]?.name||'Naqd pul')} · A’zo: ${esc(state.members[0])}</div><p class="section-text">${b.frequency==='monthly'?'Keyingi sana: '+prettyDate(nextMonthlyDate(b.date,b.anchorDay)):'Bir martalik to‘lov bajarilgan deb belgilanadi.'}<br>Bu amal bank kartangizdan pul yechmaydi.</p>`,()=>payBill(id),'To‘langanini qayd etish')}
function openReminders(){formType='reminders';pendingAction=null;const rs=reminders();setModal('Yaqinlashayotgan sanalar',rs.map(r=>`<div class="reminder"><span>${r.emoji}</span><div><b data-no-translate>${esc(r.title)}</b><p class="money">${esc(r.text)}</p><a href="#${r.page}" onclick="closeModal()">Bo‘limga o‘tish →</a></div></div>`).join('')||empty('Hozircha muhim eslatma yo‘q','Yaqin 7 kunlik qarzlar, to‘lovlar va oshgan limitlar shu yerda ko‘rinadi.'),false)}
function openCalculator(){formType='calculator';setModal('Jamg‘arma kalkulyatori',`<p class="section-text">Qancha vaqtda maqsadingizga yetishingizni hisoblang.</p>${field('Kerakli summa (so‘m)','calc-target','number',12000000,'id="calc-target" min="1" max="1000000000000" oninput="calculateGoal()"')}${field('Hozir yig‘ilgan (so‘m)','calc-saved','number',2000000,'id="calc-saved" min="0" max="1000000000000" oninput="calculateGoal()"')}${field('Har oy ajratiladigan (so‘m)','calc-monthly','number',1000000,'id="calc-monthly" min="1" max="1000000000000" oninput="calculateGoal()"')}<div class="calculator-result" id="calc-result" aria-live="polite"></div>`,false);calculateGoal()}
function calculateGoal(){const target=Number($('#calc-target').value),saved=Number($('#calc-saved').value),monthly=Number($('#calc-monthly').value);if(target<=0||saved<0||monthly<=0||![target,saved,monthly].every(Number.isFinite)){$('#calc-result').innerHTML='<p>Musbat va to‘g‘ri summalarni kiriting.</p>';return}let months=Math.ceil(Math.max(0,target-saved)/monthly);$('#calc-result').innerHTML=months?`<p>Maqsadingizga taxminan</p><b>${money(months)} oyda</b><p>Oyiga ${cash(monthly)} so‘m ajratilsa.<br>Bu oddiy hisob: foiz va narx o‘zgarishi kiritilmagan.</p>`:'<b>Tabriklaymiz! ✦</b><p>Maqsad uchun kerakli summa yig‘ilgan.</p>'}
function download(content,type,filename){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function downloadCSV(ts,filename){const rows=[['Sana','Nomi','Turi','Toifa','A’zo','To‘lov usuli','Summa (UZS)'],...ts.map(t=>[t.date,t.name,t.type==='income'?'Kirim':'Xarajat',t.category,t.member,t.method||'Karta',t.amount])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/^[\s]*[=+@-]/,"'$&").replace(/"/g,'""')+'"').join(',')).join('\r\n');download(csv,'text/csv;charset=utf-8',filename);toast('CSV fayl tayyor ✓')}
function exportTransactions(){downloadCSV(filteredTransactions(),'baraka-amaliyotlar.csv')}
function exportReport(){downloadCSV(periodTransactions(),'baraka-'+reportPeriod+'-hisobot.csv')}
function exportBackup(){download(JSON.stringify({app:'baraka',format:2,exportedAt:new Date().toISOString(),state},null,2),'application/json','baraka-zaxira-'+day()+'.json');toast('Zaxira nusxa tayyor ✓')}
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>10*1024*1024)throw Error('Fayl 10 MB dan katta bo‘lmasin.');const parsed=JSON.parse(await file.text());if(parsed.app&&parsed.app!=='baraka')throw Error('Bu Baraka zaxira fayli emas.');const imported=normalize(parsed.state||parsed);confirmAction('Zaxira nusxa tiklansinmi?',`<p class="section-text">Faylda ${imported.transactions.length} ta amaliyot, ${imported.goals.length} ta maqsad, ${imported.debts.length} ta qarz va ${imported.bills.length} ta to‘lov bor.<br><br>Hozirgi ma’lumotlar shu nusxa bilan <b>almashtiriladi</b>.</p>`,()=>{const before=state;state=imported;persist();render();toast('Zaxira nusxa tiklandi ✓',()=>{state=before;save('Avvalgi ma’lumotlar qaytarildi')})},'Tiklash')}catch(err){toast('Tiklab bo‘lmadi: '+err.message)}});
$('#modal').addEventListener('cancel',()=>{pendingAction=null;formType=''});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal()}});
addEventListener('hashchange',()=>{render();window.scrollTo({top:0,behavior:'instant'})});
addEventListener('keydown',e=>{if(e.altKey&&e.code==='KeyN'){e.preventDefault();openForm('transaction')}if((e.ctrlKey||e.metaKey)&&e.code==='KeyK'){e.preventDefault();if($('#modal').open)closeModal();location.hash='transactions';render();$('#search').focus()}});

function walletBalance(id,until=day()){const w=(state.wallets||[]).find(w=>w.id===id);if(!w)return 0;let n=w.opening;state.transactions.filter(t=>t.walletId===id&&t.date<=until).forEach(t=>n+=t.type==='income'?t.amount:-t.amount);(state.transfers||[]).filter(t=>t.date<=until).forEach(t=>{if(t.fromId===id)n-=t.amount;if(t.toId===id)n+=t.amount});return n}
function walletsPage(){const wallets=state.wallets||[];return `<div class="card-head"><p class="section-text">${wallets.length} ta hamyon · Jami: ${cash(wallets.reduce((s,w)=>s+walletBalance(w.id),0))} so‘m</p><div class="settings-actions"><button class="secondary" onclick="openForm('transfer')">${icon('swap')} O‘tkazma</button><button class="primary" onclick="openForm('wallet')">${icon('plus')} Hamyon</button></div></div><div class="triple-grid">${wallets.map(w=>`<section class="card wallet-card ${w.type==='card'?'wallet-bank':''}"><div class="card-head"><span class="wallet-symbol">${icon(w.type==='cash'?'wallet':'grid')}</span><span class="badge">${w.type==='cash'?'Naqd pul':'Bank kartasi'} · UZS</span></div><h2>${esc(w.name)}</h2><div class="big-value">${cash(walletBalance(w.id))}<small>so‘m</small></div><small>Boshlang‘ich qoldiq: ${cash(w.opening)} so‘m</small><div class="wallet-footer"><button class="text-button" onclick="openForm('wallet','${w.id}')">${icon('edit')} Tahrirlash</button><button class="text-button" onclick="removeWallet('${w.id}')" aria-label="Hamyonni o‘chirish">${icon('trash')}</button></div></section>`).join('')}</div><section class="card"><div class="card-head"><div><h2>Hamyonlar orasidagi o‘tkazmalar</h2><p>Ichki o‘tkazma kirim yoki xarajat hisoblanmaydi</p></div></div>${[...(state.transfers||[])].sort((a,b)=>b.date.localeCompare(a.date)).map(t=>`<div class="row"><div class="row-icon">${icon('swap')}</div><div class="row-info"><b data-no-translate>${esc(wallets.find(w=>w.id===t.fromId)?.name)} → ${esc(wallets.find(w=>w.id===t.toId)?.name)}</b><small>${prettyDate(t.date)} ${t.note?' · '+esc(t.note):''}</small></div><div class="row-amount">${cash(t.amount)}<small>so‘m</small></div><button class="icon-button" onclick="removeTransfer('${t.id}')" aria-label="O‘tkazmani o‘chirish">${icon('trash')}</button></div>`).join('')||empty('Hozircha o‘tkazmalar yo‘q','Naqd pul yechish yoki kartaga kiritishni shu yerda qayd eting.')}</section><div class="form-note">Bu hisob hamyonlardagi mablag‘larni kuzatadi. Bank balansini avtomatik olmaydi va kartalar orasida haqiqiy pul o‘tkazmaydi.</div>`}
function featureForm(type,id,preset){const w=state.wallets?.find(w=>w.id===id)||{};
 if(type==='wallet'){return{id,title:id?'Hamyonni tahrirlash':'Yangi hamyon',html:nameField('Hamyon nomi',w.name||'',50)+select('Turi','walletType',[['cash','Naqd pul'],['card','Bank kartasi']],w.type||'card')+field('Boshlang‘ich qoldiq (so‘m)','opening','number',w.opening??0,'required min="-1000000000000" max="1000000000000" step="1"')+'<p class="section-text">Karta raqami, amal muddati yoki CVV kiritmang. Faqat hisob nomi va qoldiq kerak.</p>'}}
 if(type==='transfer')return{title:'Hamyonlar orasida o‘tkazma',html:select('Qaysi hamyondan','fromId',state.wallets.map(w=>[w.id,w.name]))+select('Qaysi hamyonga','toId',state.wallets.map(w=>[w.id,w.name]),state.wallets[1]?.id)+amountField('Summa (so‘m)','amount')+dateField('Sana')+field('Izoh (ixtiyoriy)','note','text','','maxlength="100"')};
 if(type==='utility'){const u=(state.utilities||[]).find(u=>u.id===id)||{};return{title:id?'Abonent hisobini tahrirlash':'Kommunal hisob qo‘shish',html:nameField('Hisob nomi (masalan: Uy elektr)',u.name||'',60)+select('Xizmat','service',Object.entries(utilityServices()).map(([k,v])=>[k,v.icon+' '+v.name]),u.service||'electricity')+field('Abonent hisob raqami','accountNumber','text',u.accountNumber||'','required maxlength="40" autocomplete="off"')+field('Viloyat / tuman','region','text',u.region||'','required maxlength="80"')+'<div class="form-note">Hisob qo‘shish operator bilan ulanish degani emas. Qarzdorlik va onlayn to‘lov operator API’si ulangandan keyin ishlaydi.</div>'}}
 if(type==='utility-pay'){const u=state.utilities.find(u=>u.id===id);return{title:'Kommunal to‘lov',html:`<div class="form-note">${esc(u.name)} · ${esc(u.accountNumber)}<br>Pul operatorning rasmiy to‘lov sahifasida tasdiqlanadi.</div>`+amountField('Summa (so‘m)','amount')+select('Hisobga olinadigan hamyon','walletId',state.wallets.map(w=>[w.id,w.name]))+'<p class="section-text">Holat faqat operatorning server tasdig‘idan keyin “To‘landi” bo‘ladi.</p>'}}
 return null;
}
function commitFeature(d){
 if(formType==='wallet'){const opening=Number(d.opening);if(!Number.isSafeInteger(opening)||Math.abs(opening)>1e12)throw Error('Boshlang‘ich qoldiq noto‘g‘ri.');if(!activeId&&state.wallets.length>=30)throw Error('Eng ko‘pi 30 ta hamyon.');const w={id:activeId||uid(),name:d.name,type:d.walletType==='cash'?'cash':'card',opening};if(activeId)state.wallets=state.wallets.map(x=>x.id===activeId?w:x);else state.wallets.push(w);return true}
 if(formType==='transfer'){if(d.fromId===d.toId)throw Error('Ikki xil hamyonni tanlang.');if(!state.wallets.some(w=>w.id===d.fromId)||!state.wallets.some(w=>w.id===d.toId))throw Error('Hamyon topilmadi.');if(walletBalance(d.fromId,d.date)<d.amount)throw Error('Bu sanadagi hamyon qoldig‘i yetarli emas. Avval kirim yoki boshlang‘ich qoldiqni tekshiring.');state.transfers.push({id:uid(),...d});return true}
 if(formType==='utility'){const u={id:activeId||uid(),name:d.name,service:d.service,accountNumber:d.accountNumber.trim(),region:d.region.trim()};if(!u.accountNumber||!u.region)throw Error('Abonent raqami va hududni kiriting.');if(activeId)state.utilities=state.utilities.map(x=>x.id===activeId?u:x);else state.utilities.push(u);return true}
 return false;
}
function removeWallet(id){if(state.wallets.length===1){toast('Kamida bitta hamyon qolishi kerak.');return}if(state.transactions.some(t=>t.walletId===id)||state.transfers.some(t=>t.fromId===id||t.toId===id)){toast('Hamyon amaliyotlarda ishlatilgan. Avval tegishli yozuvlarni o‘zgartiring.');return}confirmAction('Hamyon o‘chirilsinmi?','<p class="section-text">Hamyon va uning boshlang‘ich qoldig‘i o‘chiriladi.</p>',()=>{state.wallets=state.wallets.filter(w=>w.id!==id);save()})}
function removeTransfer(id){confirmAction('O‘tkazma o‘chirilsinmi?','<p class="section-text">O‘tkazma ta’siri ikkala hamyondan olib tashlanadi.</p>',()=>{state.transfers=state.transfers.filter(t=>t.id!==id);save()})}
function utilityServices(){return{electricity:{name:'Elektr energiyasi',icon:'⚡'},gas:{name:'Tabiiy gaz',icon:'🔥'},water:{name:'Ichimlik suvi',icon:'💧'},heating:{name:'Issiqlik ta’minoti',icon:'♨️'},waste:{name:'Chiqindi xizmati',icon:'♻️'}}}
function utilitiesPage(){const connected=!!globalThis.barakaCloud?.status?.utilities?.configured;return `<div class="utility-status ${connected?'connected':''}"><div class="insight-icon">${icon('home')}</div><div><b>${connected?'Kommunal operator ulangan':'Kommunal operator hali ulanmagan'}</b><p>${connected?'Qarzdorlik operator orqali tekshiriladi. To‘lov faqat rasmiy tasdiqdan keyin qayd etiladi.':'Abonent hisoblarini saqlashingiz mumkin. Haqiqiy qarzdorlik va pul o‘tkazish uchun operator bilan rasmiy API ulanishi kerak.'}</p></div><span class="badge ${connected?'good':'warn'}">${connected?'API faol':'Ulanish kutilmoqda'}</span></div><div class="card-head section-gap"><h2>Uy hisoblari</h2><button class="primary" onclick="openForm('utility')">${icon('plus')} Abonent qo‘shish</button></div><div class="triple-grid">${(state.utilities||[]).map(u=>`<section class="card utility-card"><div class="goal-visual"><span class="goal-emoji">${utilityServices()[u.service].icon}</span><span class="badge">${utilityServices()[u.service].name}</span></div><h2>${esc(u.name)}</h2><p class="section-text">${esc(u.region)}<br>Abonent: <b data-no-translate>${esc(u.accountNumber)}</b></p><div class="utility-balance" id="utility-balance-${u.id}"><small>Operator qarzdorligi</small><b>${connected?'Tekshirilmagan':'Ma’lumot ulanmagan'}</b></div><div class="goal-actions"><button class="secondary" ${connected?'':'disabled'} onclick="lookupUtility('${u.id}')">Tekshirish</button><button class="primary" ${connected?'':'disabled'} onclick="openForm('utility-pay','${u.id}')">To‘lash ↗</button></div><div class="wallet-footer"><button class="text-button" onclick="openForm('utility','${u.id}')">${icon('edit')} Tahrirlash</button><button class="text-button" onclick="removeUtility('${u.id}')">${icon('trash')}</button></div></section>`).join('')}</div>${state.utilities?.length?'':`<section class="card">${empty('Uyingizning birinchi hisobini qo‘shing','Elektr, gaz, suv, issiqlik va chiqindi hisoblarini bir joyda saqlang.')}</section>`}<section class="card section-gap"><div class="card-head"><h2>Operator orqali to‘lovlar</h2><button class="text-button" onclick="loadUtilityPayments()">Yangilash ↻</button></div><div id="utility-payment-list"><p class="section-text">Hisobga kirgandan keyin operator tasdiqlagan to‘lovlar shu yerda ko‘rinadi.</p></div></section><div class="form-note">“To‘lovlar” bo‘limidagi qo‘lda qayd etish bank to‘lovi emas. Ushbu bo‘limdagi “To‘lash” rasmiy operatorga ulanadi; karta ma’lumotlari Baraka’da olinmaydi.</div>`}
function removeUtility(id){confirmAction('Abonent hisobi o‘chirilsinmi?','<p class="section-text">Bu faqat saqlangan hisobni o‘chiradi, xizmat shartnomasini bekor qilmaydi.</p>',()=>{state.utilities=state.utilities.filter(u=>u.id!==id);save()})}
async function lookupUtility(id){try{const r=await globalThis.barakaCloud.request('/api/utilities/lookup','POST',{accountId:id}),el=$('#utility-balance-'+id);if(el)el.innerHTML=`<small>Operator qoldig‘i · ${esc(r.source)}</small><b>${cash(r.balance)} so‘m</b><small>Tekshirildi: ${new Date(r.updatedAt).toLocaleString('uz-UZ')}</small>`}catch(e){toast(e.message)}}
async function loadUtilityPayments(){if(!globalThis.barakaCloud?.user)return;try{const {payments}=await globalThis.barakaCloud.request('/api/utilities/payments');if($('#utility-payment-list'))$('#utility-payment-list').innerHTML=payments.map(p=>`<div class="row"><div class="row-icon">${icon('home')}</div><div class="row-info"><b data-no-translate>${esc(p.name)}</b><small>${new Date(p.createdAt).toLocaleString('uz-UZ')}</small><span class="badge ${p.status==='paid'?'good':p.status==='failed'?'bad':'warn'}">${({paid:'Operator tasdiqlagan',failed:'Bajarilmagan',pending:'Operator tasdig‘i kutilmoqda',unknown:'Holatni operator bilan tekshiring'})[p.status]}</span></div><div class="row-amount">${cash(p.amount)}<small>so‘m</small></div></div>`).join('')||empty('Haqiqiy to‘lovlar hali yo‘q')}catch(e){toast(e.message)}}

let calendarCursor=new Date(new Date().getFullYear(),new Date().getMonth(),1),calendarSelected=day();
function calendarEvents(start,end){const events=[];const add=(date,title,kind,amount,route)=>{if(date>=start&&date<=end)events.push({date,title,kind,amount,route})};state.bills.filter(b=>!b.done).forEach(b=>{let date=b.date;for(let i=0;i<240&&date<=end;i++){add(date,b.name,'bill',b.amount,'bills');if(b.frequency!=='monthly')break;date=nextMonthlyDate(date,b.anchorDay||Number(b.date.slice(-2)))}});state.debts.filter(d=>remainingDebt(d)>0).forEach(d=>add(d.date,d.name+' · qarz','debt',remainingDebt(d),'debts'));state.goals.filter(g=>g.date&&g.saved<g.target).forEach(g=>add(g.date,g.name,'goal',Math.max(0,g.target-g.saved),'goals'));state.transactions.forEach(t=>add(t.date,t.name,t.type,t.amount,'transactions'));events.push(...BarakaDay.calendarEvents(start,end));return events.sort((a,b)=>a.date.localeCompare(b.date))}
function calendarPage(){const first=dateKey(calendarCursor),last=dateKey(new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()+1,0)),events=calendarEvents(first,last),offset=(calendarCursor.getDay()+6)%7,days=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()+1,0).getDate(),selected=events.filter(e=>e.date===calendarSelected),names={bill:'To‘lov',debt:'Qarz',goal:'Maqsad',income:'Kirim',expense:'Xarajat',task:'Vazifa',appointment:'Uchrashuv / eslatma'};return `<div class="grid calendar-layout"><section class="card"><div class="card-head"><h2>${calendarCursor.toLocaleDateString('uz-UZ',{month:'long',year:'numeric'})}</h2><div class="calendar-controls"><button class="icon-button" onclick="moveCalendar(-1)" aria-label="Oldingi oy">‹</button><button class="secondary" onclick="resetCalendar()">Bugun</button><button class="icon-button" onclick="moveCalendar(1)" aria-label="Keyingi oy">›</button></div></div><div class="calendar-grid">${['Du','Se','Chor','Pay','Ju','Sha','Yak'].map(d=>`<div class="weekday">${d}</div>`).join('')}${'<div class="calendar-blank"></div>'.repeat(offset)}${Array.from({length:days},(_,i)=>{const date=dateKey(new Date(calendarCursor.getFullYear(),calendarCursor.getMonth(),i+1)),es=events.filter(e=>e.date===date);return `<button class="calendar-day ${date===day()?'today':''} ${date===calendarSelected?'selected':''}" onclick="selectCalendar('${date}')" aria-label="${prettyDate(date)}, ${es.length} ta voqea" aria-pressed="${date===calendarSelected}"><b>${i+1}</b><span class="event-dots">${[...new Set(es.map(e=>e.kind))].slice(0,3).map(k=>`<i class="event-${k}"></i>`).join('')}</span></button>`}).join('')}</div><div class="calendar-legend"><span><i class="event-bill"></i>To‘lov</span><span><i class="event-debt"></i>Qarz</span><span><i class="event-goal"></i>Maqsad</span><span><i class="event-income"></i>Kirim</span><span><i class="event-expense"></i>Xarajat</span></div></section><section class="card"><div class="card-head"><div><h2>${prettyDate(calendarSelected)}</h2><p>Tanlangan kun voqealari</p></div><button class="text-button" onclick="openCalendarBill()">${icon('plus')} Reja</button></div>${selected.map(e=>`<a class="row calendar-event" href="#${e.route}"><div class="row-icon">${icon(e.kind==='goal'?'target':e.kind==='debt'?'hand':e.kind==='bill'?'calendar':'swap')}</div><div class="row-info"><b data-no-translate>${esc(e.title)}</b><small>${names[e.kind]}</small></div>${e.amount===null?'':`<span class="row-amount">${cash(e.amount)}<small>so‘m</small></span>`}</a>`).join('')||empty('Bu kun uchun voqea yo‘q','To‘lov yoki reja qo‘shishingiz mumkin.')}<div class="chart-note">${events.filter(e=>e.kind==='bill'||e.kind==='debt').length} ta to‘lov / qarz sanasi shu oyga to‘g‘ri keladi. Oylik to‘lovlar kelgusi oylar uchun ham ko‘rsatiladi.</div></section></div>`}
function moveCalendar(n){calendarCursor=new Date(calendarCursor.getFullYear(),calendarCursor.getMonth()+n,1);calendarSelected=dateKey(calendarCursor);render()}
function selectCalendar(date){calendarSelected=date;render()}
function resetCalendar(){calendarCursor=new Date(new Date().getFullYear(),new Date().getMonth(),1);calendarSelected=day();render()}
function openCalendarBill(){openForm('bill');$('#fields input[name=date]').value=calendarSelected}

$('#today').textContent=new Date().toLocaleDateString('uz-UZ',{day:'numeric',month:'long',year:'numeric'});
paintIcons();render();
if(!storageOK)setTimeout(()=>toast('Saqlangan ma’lumotlarni o‘qib bo‘lmadi. Brauzer xotirasi sozlamalarini tekshiring.'),500);
